package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct {
	ErId    string          // PIC X(5) @0 len=5
	ErDept  string          // PIC X(3) @5 len=3
	ErHours decimal.Decimal // PIC 9(3)V9 @8 len=4
	ErRate  decimal.Decimal // PIC 9(3)V99 @12 len=5
}

var WsEofFlag string // PIC X len=1 = "N"
var WsFirstFlag string
var WsPrevDept string

var WsRegHours decimal.Decimal
var WsOtHours decimal.Decimal
var WsGross decimal.Decimal
var WsDeptTotal decimal.Decimal
var WsDeptCount int64
var WsGrandTotal decimal.Decimal
var WsGrandCount int64

var WsHoursEd string
var WsRateEd string
var WsGrossEd string
var WsDeptEd string
var WsGrandEd string

var EmpRecVar EmpRec

var empFile *os.File
var scanner *bufio.Scanner

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func pow10(n int) decimal.Decimal {
	return decimal.New(1, int32(n))
}

// storeDecimal truncates toward zero to scale and drops high-order digits
func storeDecimal(v decimal.Decimal, intDigits, scale int) decimal.Decimal {
	// truncate toward zero to scale
	v = v.Truncate(int32(scale))
	if intDigits+scale == 0 {
		return decimal.Zero
	}
	// scaled integer = v * 10^scale, exact after truncate
	scaled := v.Shift(int32(scale)) // scale -> integer value
	// total digits that fit
	totalDigits := intDigits + scale
	mod := pow10(totalDigits) // 10^totalDigits

	// work with sign magnitude
	neg := scaled.IsNegative()
	absScaled := scaled.Abs()
	// absScaled is integer (scale 0)
	if absScaled.Cmp(mod) >= 0 {
		absScaled = absScaled.Mod(mod)
		// Mod for decimal may keep decimal scale; ensure integer
		// reconstruct
		if neg {
			scaled = absScaled.Neg().Truncate(0)
		} else {
			scaled = absScaled.Truncate(0)
		}
	} else {
		// keep as is
		scaled = scaled.Truncate(0)
	}
	// back to decimal with scale
	return scaled.Shift(int32(-scale))
}

func storeCount(v int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	// COBOL keeps low-order digits; for positive counts just modulo
	// handle negative not needed
	if v >= mod || v < 0 {
		v = v % mod
		if v < 0 {
			v += mod
		}
	}
	return v
}

func parsePIC9(s string, scale int) decimal.Decimal {
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.Zero
	}
	// keep only digits and sign
	// s should be digits only
	// parse as integer
	d, err := decimal.NewFromString(t)
	if err != nil {
		// if contains non-digit, try to extract digits
		// fallback to 0
		return decimal.Zero
	}
	// digits represent value *10^scale in integer form
	// so shift -scale
	return d.Shift(int32(-scale))
}

func formatEdited(v decimal.Decimal, pic string) string {
	neg := v.IsNegative()
	if neg {
		v = v.Abs()
	}
	dotIdx := strings.Index(pic, ".")
	var intPic, decPic string
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		decPic = pic[dotIdx+1:]
	} else {
		intPic = pic
		decPic = ""
	}
	intPlaceholders := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intPlaceholders++
		}
	}
	decPlaceholders := 0
	for _, c := range decPic {
		if c == 'Z' || c == '9' {
			decPlaceholders++
		}
	}
	// Prepare integer and decimal digit strings
	// We need v rounded/truncated to decPlaceholders.
	// The source values already have correct scale, so just truncate/round to decPlaceholders
	// Use Truncate to keep exact; but for formatting we quantize.
	// Use Round for safety? COBOL MOVE does not round, but we mimic exact.
	// We'll quantize by truncating towards zero after ensuring scale.
	// Get integer and fractional parts via Shift
	// total integer value = floor(v)
	// For extracting digits we use string fixed

	// Ensure v has at most decPlaceholders decimal places by truncating (if more, truncate)
	// If fewer, it will be padded.
	vq := v.Truncate(int32(decPlaceholders))
	// For high-order drop, we need integer part modulo 10^{intPlaceholders}
	// Get integer part
	intPart := vq.Truncate(0).Abs()
	// fractional part
	// Build integer digits string of length intPlaceholders
	var intDigits string
	// intPart may be big, but we need low-order digits
	if intPlaceholders > 0 {
		// scaled integer of intPart
		// Use string representation
		// Get intPart as decimal integer
		// Convert to string without exponent
		s := intPart.StringFixed(0) // no decimals
		// s is like "1234"
		// Pad / truncate to intPlaceholders (keep low-order)
		if len(s) > intPlaceholders {
			s = s[len(s)-intPlaceholders:]
		} else if len(s) < intPlaceholders {
			s = strings.Repeat("0", intPlaceholders-len(s)) + s
		}
		intDigits = s
	}
	// fractional digits
	var fracDigits string
	if decPlaceholders > 0 {
		// get fractional part: vq - intPart
		// Use vq StringFixed
		s := vq.StringFixed(int32(decPlaceholders)) // includes dot
		// s = "1234.56"
		idx := strings.Index(s, ".")
		if idx >= 0 {
			fracDigits = s[idx+1:]
			// ensure length
			if len(fracDigits) < decPlaceholders {
				fracDigits += strings.Repeat("0", decPlaceholders-len(fracDigits))
			} else if len(fracDigits) > decPlaceholders {
				fracDigits = fracDigits[:decPlaceholders]
			}
		} else {
			fracDigits = strings.Repeat("0", decPlaceholders)
		}
	}

	// Build result array
	// We'll fill intPic placeholders with intDigits
	// Map intDigits to placeholder positions left to right
	resultInt := []rune(intPic)
	// placeholder indices in order
	placeholderPos := []int{}
	for i, c := range resultInt {
		if c == 'Z' || c == '9' {
			placeholderPos = append(placeholderPos, i)
		}
	}
	// Fill digits
	for i, pos := range placeholderPos {
		ch := intDigits[i]
		resultInt[pos] = rune(ch)
	}
	// Apply Z suppression
	// suppressed flag indicates we are still in leading zero suppression region
	suppressed := true
	for idx, pos := range placeholderPos {
		picChar := rune(intPic[pos]) // original pic char
		digit := resultInt[pos]
		if digit != '0' {
			suppressed = false
			// keep digit
			continue
		}
		// digit == '0'
		if suppressed && picChar == 'Z' {
			resultInt[pos] = ' '
			// remain suppressed
		} else {
			// picChar == '9' => keep '0' and end suppression
			// also if digit zero but not suppressed? (should not happen because once non-zero seen suppressed false)
			suppressed = false
		}
		_ = idx
	}
	// Commas become spaces if all placeholders to the left are spaces
	for i, c := range resultInt {
		if c == ',' {
			// check if all placeholder positions with pos < i are spaces
			allSpace := true
			for _, pp := range placeholderPos {
				if pp < i {
					if resultInt[pp] != ' ' {
						allSpace = false
						break
					}
				} else {
					break
				}
			}
			if allSpace {
				resultInt[i] = ' '
			}
		}
	}

	var sb strings.Builder
	if neg {
		// COBOL would show sign elsewhere; not needed for tests
		sb.WriteRune('-')
	}
	sb.WriteString(string(resultInt))
	if dotIdx >= 0 {
		sb.WriteRune('.')
		// decPic may contain literals like ','? not in these pics
		// For dec part, handle Z/9 similarly (Z in decimals suppresses zero)
		// Our decPics are all 9s, so just write fracDigits
		// If decPic contains Z, we would need suppression, but not needed
		// Map fracDigits to decPic placeholders
		decRunes := []rune(decPic)
		posIdx := 0
		for _, c := range decRunes {
			if c == 'Z' || c == '9' {
				if posIdx < len(fracDigits) {
					ch := fracDigits[posIdx]
					// For Z in decimal part, if value is zero maybe suppress? Not needed
					sb.WriteRune(rune(ch))
				} else {
					sb.WriteRune('0')
				}
				posIdx++
			} else {
				sb.WriteRune(c)
			}
		}
	}
	return sb.String()
}

func formatCount(c int64, digits int) string {
	// zero-padded to digits width
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	// already stored modulo, but ensure positive
	if c < 0 {
		c = ((c % mod) + mod) % mod
	}
	s := fmt.Sprintf("%0*d", digits, c)
	if len(s) > digits {
		s = s[len(s)-digits:]
	}
	return s
}

// Paragraphs

func ReadPara() {
	if scanner.Scan() {
		line := scanner.Text()
		if len(line) < 17 {
			line = line + strings.Repeat(" ", 17-len(line))
		} else if len(line) > 17 {
			line = line[:17]
		}
		EmpRecVar.ErId = line[0:5]
		EmpRecVar.ErDept = line[5:8]
		EmpRecVar.ErHours = parsePIC9(line[8:12], 1)
		EmpRecVar.ErRate = parsePIC9(line[12:17], 2)
	} else {
		if err := scanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	if isFirstRecord() {
		WsPrevDept = EmpRecVar.ErDept
		WsFirstFlag = "N"
	} else {
		if EmpRecVar.ErDept != WsPrevDept {
			DeptBreakPara()
			WsPrevDept = EmpRecVar.ErDept
		}
	}
	PayPara()
	ReadPara()
}

func PayPara() {
	forty := decimal.New(40, 0)
	if EmpRecVar.ErHours.Cmp(forty) > 0 {
		WsRegHours = storeDecimal(decimal.New(40, 0), 3, 1)
		WsOtHours = storeDecimal(EmpRecVar.ErHours.Sub(forty), 3, 1)
	} else {
		WsRegHours = storeDecimal(EmpRecVar.ErHours, 3, 1)
		WsOtHours = storeDecimal(decimal.Zero, 3, 1)
	}
	onePointFive := decimal.New(15, -1) // 1.5
	calc := WsRegHours.Mul(EmpRecVar.ErRate).Add(WsOtHours.Mul(EmpRecVar.ErRate).Mul(onePointFive))
	calcRounded := calc.Round(2) // half away for positive
	WsGross = storeDecimal(calcRounded, 7, 2)

	WsDeptTotal = storeDecimal(WsDeptTotal.Add(WsGross), 9, 2)
	WsDeptCount = storeCount(WsDeptCount+1, 3)
	WsGrandTotal = storeDecimal(WsGrandTotal.Add(WsGross), 11, 2)
	WsGrandCount = storeCount(WsGrandCount+1, 5)

	WsHoursEd = formatEdited(EmpRecVar.ErHours, "ZZ9.9")
	WsRateEd = formatEdited(EmpRecVar.ErRate, "ZZ9.99")
	WsGrossEd = formatEdited(WsGross, "Z,ZZZ,ZZ9.99")

	// DISPLAY ER-ID " " ER-DEPT " " WS-HOURS-ED " " WS-RATE-ED " " WS-GROSS-ED.
	fmt.Printf("%s %s %s %s %s\n", EmpRecVar.ErId, EmpRecVar.ErDept, WsHoursEd, WsRateEd, WsGrossEd)
}

func DeptBreakPara() {
	WsDeptEd = formatEdited(WsDeptTotal, "ZZZ,ZZZ,ZZ9.99")
	countStr := formatCount(WsDeptCount, 3)
	fmt.Printf("  DEPT %s EMPLOYEES: %s TOTAL: %s\n", WsPrevDept, countStr, WsDeptEd)
	WsDeptTotal = storeDecimal(decimal.Zero, 9, 2)
	WsDeptCount = 0
}

func GrandPara() {
	WsGrandEd = formatEdited(WsGrandTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := formatCount(WsGrandCount, 5)
	fmt.Printf("GRAND TOTAL (%s): %s\n", countStr, WsGrandEd)
}

func main() {
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevDept = strings.Repeat(" ", 3)
	WsRegHours = decimal.Zero
	WsOtHours = decimal.Zero
	WsGross = decimal.Zero
	WsDeptTotal = decimal.Zero
	WsDeptCount = 0
	WsGrandTotal = decimal.Zero
	WsGrandCount = 0

	// OPEN INPUT EMP-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			// treat as empty file
			WsEofFlag = "Y"
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		empFile = f
		defer empFile.Close()
		scanner = bufio.NewScanner(empFile)
		// allow long lines
		const maxCapacity = 1024 * 1024
		buf := make([]byte, 0, 64*1024)
		scanner.Buffer(buf, maxCapacity)
		ReadPara()
		// PERFORM PROCESS-PARA UNTIL INPUT-DONE
		for !isInputDone() {
			ProcessPara()
		}
		if !isFirstRecord() {
			DeptBreakPara()
		}
		// CLOSE EMP-FILE already deferred
		GrandPara()
		return
	}
	// If file not exist, still need to handle break logic: no records
	if !isFirstRecord() {
		DeptBreakPara()
	}
	GrandPara()
}
